const ANCHOR_CLASS_NAME = "text-blue-600 underline break-all";

// Matches only http:// and https:// URLs. Any other scheme (ftp, mailto,
// file, javascript, data, ...), a misspelled prefix (htp://) or a schemeless
// host (example.com) will not match, so it never becomes an anchor.
const URL_REGEX = /https?:\/\/[^\s<]+/g;

// Characters that may cling to the end of a URL as sentence punctuation and
// should be excluded from the linkified href.
const TRAILING_PUNCTUATION = ".,;:!?'\"";

type TrimmedUrl = {
  url: string;
  trailing: string;
};

const countOccurrences = (value: string, char: string): number => {
  let count = 0;
  for (const c of value) {
    if (c === char) count += 1;
  }
  return count;
};

// Strips trailing punctuation as well as unbalanced enclosing brackets/parens
// (e.g. "(http://a.com)" -> "http://a.com") while preserving balanced ones
// that are part of the URL (e.g. Wikipedia "/Foo_(bar)").
const trimUrl = (raw: string): TrimmedUrl => {
  let url = raw;
  let trailing = "";

  while (url.length > 0) {
    const last = url[url.length - 1];

    if (TRAILING_PUNCTUATION.includes(last)) {
      trailing = last + trailing;
      url = url.slice(0, -1);
      continue;
    }

    if (last === ")" || last === "]" || last === "}") {
      const open = last === ")" ? "(" : last === "]" ? "[" : "{";
      if (countOccurrences(url, last) > countOccurrences(url, open)) {
        trailing = last + trailing;
        url = url.slice(0, -1);
        continue;
      }
    }

    break;
  }

  return { url, trailing };
};

// Splits a string into text segments and anchor elements for every embedded
// http(s) URL. Rendering happens through React (never dangerouslySetInnerHTML),
// so any script tags or markup in the text are escaped rather than executed.
const linkify = (text: string): React.ReactNode[] => {
  const nodes: React.ReactNode[] = [];
  const regex = new RegExp(URL_REGEX);
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let key = 0;

  while ((match = regex.exec(text)) !== null) {
    const raw = match[0];
    const start = match.index;
    const { url, trailing } = trimUrl(raw);

    if (start > lastIndex) {
      nodes.push(
        <React.Fragment key={`text-${key}`}>
          {text.slice(lastIndex, start)}
        </React.Fragment>,
      );
    }

    nodes.push(
      <a
        key={`link-${key}`}
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        className={ANCHOR_CLASS_NAME}
        onClick={(event) => event.stopPropagation()}
      >
        {url}
      </a>,
    );

    if (trailing) {
      nodes.push(
        <React.Fragment key={`trail-${key}`}>{trailing}</React.Fragment>,
      );
    }

    lastIndex = start + raw.length;
    key += 1;
  }

  if (lastIndex < text.length) {
    nodes.push(
      <React.Fragment key={`text-${key}`}>
        {text.slice(lastIndex)}
      </React.Fragment>,
    );
  }

  return nodes;
};

const LinkifyText = ({ children }: { children?: React.ReactNode }) => {
  // null / undefined render as empty content.
  if (children === null || children === undefined) {
    return <></>;
  }

  // Numbers are rendered as their string representation; they can never
  // contain a URL, so no linkification is attempted.
  if (typeof children === "number") {
    return <>{String(children)}</>;
  }

  // Non-string React nodes are rendered as-is.
  if (typeof children !== "string") {
    return <>{children}</>;
  }

  // Plain strings without an http(s) URL are rendered verbatim so the
  // container's innerHTML matches the text exactly (no wrapper element).
  if (!children.includes("http")) {
    return <>{children}</>;
  }

  return <>{linkify(children)}</>;
};

export default LinkifyText;
